/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { DiracDelta, InverseLaplaceTransform, LaplaceTransform, Subs, Sym, SymFunction, add, derivative, exp, inverseLaplaceTransform, laplaceCorrespondence, laplaceInitialConds, laplaceTransform, mul, pow, rational, symbols } from '../../../src';
import { at, sympyMatches, sympyStr } from '../../sympy-str';

describe("doctests of sympy.integrals.laplace", () => {
  it("inverse_laplace_transform(exp(-a*s)/s, s, t)", () => {
    const [s, t] = symbols('s t');
    const a = new Sym('a', { positive: true });
    expect(sympyStr(inverseLaplaceTransform(mul(pow(s, -1), exp(mul(-1, s, a))), s, t))).toBe('Heaviside(-a + t)');
  });
  it("laplace_correspondence(f, {y: Y, z: Z})", () => {
    const [s, t] = symbols('s t');
    expect(sympyStr(laplaceCorrespondence(add(mul(-1, (SymFunction('y'))(rational(0))), mul(s, new LaplaceTransform((SymFunction('y'))(t), t, s)), new LaplaceTransform((SymFunction('z'))(t), t, s)), new Map([[SymFunction('y', {}), SymFunction('Y', {})], [SymFunction('z', {}), SymFunction('Z', {})]])))).toBe('s*Y(s) + Z(s) - y(0)');
  });
  it("laplace_correspondence(f, {y: Y})", () => {
    const [s, t] = symbols('s t');
    expect(sympyStr(laplaceCorrespondence(new InverseLaplaceTransform((SymFunction('Y'))(s), s, t), new Map([[SymFunction('y', {}), SymFunction('Y', {})]])))).toBe('y(t)');
  });
  it("laplace_initial_conds(g, t, {y: [2, 4, 8, 16, 32]})", () => {
    const [t, s] = symbols('t s');
    expect(sympyStr(laplaceInitialConds(add(mul(-1, Subs(derivative((SymFunction('y'))(t), [[t, 2]]), [t], [rational(0)])), mul(pow(s, 3), (SymFunction('Y'))(s)), mul(-1, s, Subs(derivative((SymFunction('y'))(t), [[t, 1]]), [t], [rational(0)])), mul(-1, pow(s, 2), (SymFunction('y'))(rational(0)))), t, new Map([[SymFunction('y', {}), [2, 4, 8, 16, 32]]])))).toBe('s**3*Y(s) - 2*s**2 - 4*s - 8');
  });
  it("laplace_transform(t**4, t, s)", () => {
    const [t, s] = symbols('t s');
    const v1 = laplaceTransform(pow(t, 4), t, s);
    expect(sympyMatches([at(v1, 0), at(v1, 1), at(v1, 2)], '(24/s**5, 0, True)')).toBe(true);
  });
  it("laplace_transform(t**a, t, s)", () => {
    const [t, a, s] = symbols('t a s');
    const v1 = laplaceTransform(pow(t, a), t, s);
    expect(sympyMatches([at(v1, 0), at(v1, 1), at(v1, 2)], '(gamma(a + 1)/(s*s**a), 0, re(a) > -1)')).toBe(true);
  });
  it("laplace_transform(DiracDelta(t)-a*exp(-a*t), t, s, simplify=True)", () => {
    const [a, t, s] = symbols('a t s');
    const v1 = laplaceTransform(add(mul(-1, a, exp(mul(-1, a, t))), DiracDelta(t)), t, s, { simplify: true });
    expect(sympyMatches([at(v1, 0), at(v1, 1), at(v1, 2)], '(s/(a + s), -re(a), True)')).toBe(true);
  });
  it("inverse_laplace_transform(Xs, s, t)", () => {
    const [m, v, k, d, s, t] = symbols('m v k d s t');
    expect(sympyStr(inverseLaplaceTransform(mul(m, v, pow(add(k, mul(d, s), mul(m, pow(s, 2))), -1)), s, t))).toBe('2*v*exp(-d*t/(2*m))*sin(t*sqrt((-d**2 + 4*k*m)/m**2)/2)*Heaviside(t)/sqrt((-d**2 + 4*k*m)/m**2)');
  });
  it("F", () => {
    const [d, s, k, m, t, v] = symbols('d s k m t v');
    expect(sympyStr(laplaceInitialConds(add(mul(d, add(mul(-1, (SymFunction('x'))(rational(0))), mul(s, (SymFunction('X'))(s)))), mul(k, (SymFunction('X'))(s)), mul(m, add(mul(-1, Subs(derivative((SymFunction('x'))(t), [[t, 1]]), [t], [rational(0)])), mul(pow(s, 2), (SymFunction('X'))(s)), mul(-1, s, (SymFunction('x'))(rational(0)))))), t, new Map([[SymFunction('x', {}), [0, v]]])))).toBe('d*s*X(s) + k*X(s) + m*(s**2*X(s) - v)');
  });
});
